head.script:
scwin.onpageload = function() {
    var jsonData = [{
            "label": "input",
            "code": "input"
        },
        {
            "label": "calendar",
            "code": "calendar"
        },
        {
            "label": "checkbox",
            "code": "checkbox"
        },
        {
            "label": "select",
            "code": "select"
        },
        {
            "label": "radio",
            "code": "radio"
        }
    ];
    dlt_select.setJSON(jsonData);
    var sel_sampleData = [{
            "codeLB": "축구",
            "codeVL": "1"
        },
        {
            "codeLB": "농구",
            "codeVL": "2"
        },
        {
            "codeLB": "야구",
            "codeVL": "3"
        },
        {
            "codeLB": "배구",
            "codeVL": "4"
        }
    ];
    sel_sample.setJSON(sel_sampleData);
    //dataList1.insertRow();
    //dataList1.getRowJSON
    var arr = [];
    for (var i = 0; i < 20; i++) {
        var j1 = {
            "col1": "checkbox"
        }
        arr.push(j1);
    }
    dataList1.setJSON(arr);
    //grd.setCellMaxLength(0, 1, "4.2");
};
scwin.onpageunload = function() {};
scwin.grd_onviewchange = function(info) {
    console.log("scwin.grd_onviewchange", info);
    var inputType = info.newValue;
    //debugger;
    var obj = scwin.inputTypeCustomObj[inputType];
    grd.setCellInputType(info.rowIndex, "col2", obj);
    if (inputType === "input") {
        grd.setCellMaxLength(info.rowIndex, "col2", "5.2");
    }
};
scwin.trigger1_onclick = function(e) {
    grd.setCellMaxLength(0, 1, "5.2");
};
scwin.grd_onbeforeedit = function(row, col, value) {
    /*
        console.log("onbeforeedit", row,col,value);
		if(col == 1) {
            if(dataList1.getCellData(row,"col1") == "input") {
                grd.setCellMaxLength(row, "col2", "5.2");
            }
        } 
        */
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.checkVal = function() {
    var temp = WebSquare.logger.getLog();
    return temp.indexOf('cell의 inputType이 올바르지 않습니다') == -1;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_scrollY_div').scrollTop = 600");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_cell_5_0').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'grd_cell_5_0')");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grd___selectbox_col1_itemTable_0').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "300");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.inputTypeCustomObj = {
        calendar: {
            inputType: "calendar"
        },
        radio: {
            inputType: "radio"
        },
        checkbox: {
            inputType: "checkbox"
        },
        input: {
            inputType: "text"
        },
        select: {
            inputType: "select",
            options: {
                viewType: "icon"
            },
            itemSet: {
                nodeset: "data:sel_sample",
                label: "codeLB",
                value: "codeVL"
            }
        }
    };
    //값 변경 시 col2의 inputType을 동적으로 변경한다.
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
